      log.info("CHECKPOINT", `已删除新文件: ${file.filePath}`);
      return { action: "deleted" };
    }
    return null;
  }

  // 已有文件：恢复到快照前的内容
  const content = await this.rebuildContentBeforeSnapshot(file.filePath, snapshotId);
  if (content === null) return null;

  await Bun.write(file.filePath, content);
  log.info("CHECKPOINT", `已恢复文件: ${file.filePath}`);
  return { action: "restored" };
}
```

改造后 `undo()` 变为：

```typescript
async undo(): Promise<UndoResult | null> {
  if (!this.config.enabled) return null;

  const lastSnapshot = this.getLastSnapshot();
  if (!lastSnapshot) return null;

  const results: UndoResult["files"] = [];
  for (const file of lastSnapshot.files) {
    const result = await this.restoreFile(file, lastSnapshot.id);
    if (result) {
      results.push({ filePath: file.filePath, ...result });
    }
  }

  this.removeLastSnapshot();
  await this.saveIndex();
  return { snapshotId: lastSnapshot.id, files: results };
}
```

**收益和注意事项：**

1. **三处复用** — `undo()`、`undoFile()`、`restoreToSnapshot()` 里的 `existedBefore` 分支判断 + try/catch + 日志完全一样，都可以用 `restoreFile()` 替换。
2. **`restoreToSnapshot()` 稍有不同** — 它调用的是 `rebuildContentAtSnapshot` 而非 `rebuildContentBeforeSnapshot`，所以 `restoreFile` 需要接收一个重建策略参数（或改为传入已重建的 content）。两种方式：
   - 方案 A：`restoreFile` 接受可选的 `contentOverride?: string`，`restoreToSnapshot` 先算好 content 再传入
   - 方案 B：`restoreFile` 接受 `mode: "before" | "at"` 参数
   - 我倾向方案 A，更简单直接
3. **错误处理** — 当前三处的 try/catch 只是 warn 日志后 continue，`restoreFile` 可以统一用 try/catch 包裹，返回 null 表示失败，调用方不需要关心细节。

