下面是等价的 Python 重写，只包含 `check()` 方法所需的最小上下文：

```python
"""成本配额管理 — check() 等价重写"""

from typing import Literal, Optional, TypedDict

AlertLevel = Literal["info", "warning", "critical", "exceeded"]

LEVEL_ORDER: list[AlertLevel] = ["info", "warning", "critical", "exceeded"]


class QuotaCheckResult(TypedDict):
    level: AlertLevel
    message: str


class QuotaManager:
    def __init__(self, cost_limit: float):
        self.cost_limit = cost_limit
        self._last_alert_level: Optional[AlertLevel] = None

    def check(self, current_cost: float) -> Optional[QuotaCheckResult]:
        if self.cost_limit <= 0:
            return None

        ratio = current_cost / self.cost_limit
        level: Optional[AlertLevel] = None

        if ratio >= 1.0:
            level = "exceeded"
        elif ratio >= 0.95:
            level = "critical"
        elif ratio >= 0.80:
            level = "warning"
        elif ratio >= 0.50:
            level = "info"

        if level is None:
            return None

        # 只在级别升级时触发
        last_idx = (
            LEVEL_ORDER.index(self._last_alert_level)
            if self._last_alert_level is not None
            else -1
        )
        current_idx = LEVEL_ORDER.index(level)

        if current_idx <= last_idx:
            return None

        self._last_alert_level = level

        percent = f"{ratio * 100:.0f}"
        messages: dict[AlertLevel, str] = {
            "info": f"成本已达配额 {percent}%（${current_cost:.4f} / ${self.cost_limit:.2f}）",
            "warning": f"⚠ 成本已达配额 {percent}%（${current_cost:.4f} / ${self.cost_limit:.2f}），请注意控制用量",
            "critical": f"⚠ 成本已达配额 {percent}%（${current_cost:.4f} / ${self.cost_limit:.2f}），即将超限！",
            "exceeded": f"成本已超出配额（${current_cost:.4f} / ${self.cost_limit:.2f}），自动停止",
        }

        return {"level": level, "message": messages[level]}

    def reset_alert_level(self) -> None:
        self._last_alert_level = None
```

行为完全等价：四级阈值判定 → 级别只升不降（避免重复告警）→ 升级时返回格式化消息，否则返回 `None`。

